//! Control-in port tables of the effect nodes, generated by
//! `gen_fx_ports.py` from the port table in the private dreist-re notes
//! (extracted from each node's `InitializePorts`). Do not edit by hand.

#![allow(non_upper_case_globals)]

use super::convert::Conv;

